-- FRM-207 v3 - a person must confirm the transcribed declarations before an entry is submitted.
--
-- WHY. The first live specification scans of a Pillsbury Creme Cake Base bag (2026-09-18) each
-- misread the ingredient statement at the same place, differently each time:
--   on the bag:  ... CALCIUM ACETATE, NONFAT MILK, XANTHAN GUM, GUAR GUM, VITAL WHEAT GLUTEN ...
--   scan 1:      ... CALCIUM ACETATE, PROPYLENE GLYCOL MONO AND DIESTERS, VITAL WHEAT GLUTEN ...
--   scan 2:      ... CALCIUM ACETATE, MONOCALCIUM PHOSPHATE, VITAL WHEAT GLUTEN ...
-- Both dropped an allergen-bearing ingredient (nonfat milk) and invented one that is not on the
-- pack. The Contains boxes were right both times - they come from the Contains line by word
-- matching - but a field labelled "as printed" that silently misses the milk is worse than a blank.
--
-- THREE GUARDS, this migration is the third:
--   1. extract-package-label uses the stronger model for specification scans only.
--   2. The scan warns when the Contains line declares an allergen the transcribed ingredients do
--      not name (ingredientsMissingDeclared) - it would have caught both misreads above. The warning
--      now stays on screen until dismissed.
--   3. declarations_checked: a REQUIRED checkbox after the Contains statement, carrying
--      clearOnScanOf [ingredient_statement, contains_statement] - a scan that fills either one
--      unticks it. The form cannot be submitted until a person has read them against the pack.
-- The model can be wrong the same way twice; only 3 does not depend on it being right.
--
-- NOT DONE HERE: the submitted Pillsbury entry (63b9cb6d-...) carries scan 1's statement. It is a
-- signed record, so it is reopened and corrected by the SQF Practitioner in the app, not rewritten
-- by a migration. Submitted entries are not re-validated against a new required field.
--
-- Revised to v3, GJM, 2026-09-18. Field ids unchanged; one field added. Guarded on the v2 md5.

begin;

do $guard$
declare st text; rev text; h text;
begin
  select status, revision, md5((content->'form_schema')::text) into st, rev, h
    from public.sop_documents where sop_number = 'FRM-207';
  if (st, rev) is distinct from ('active', 'v2') then
    raise exception 'FRM-207 is %/% - expected active/v2.', st, rev;
  end if;
  if h <> 'a051050ea3198ffdd2bfce6913b580b5' then
    raise exception 'FRM-207 form_schema changed since this migration was written (md5 %).', h;
  end if;
end $guard$;

update public.sop_documents
   set content        = jsonb_set(content, '{form_schema}', $fs${"sections": [{"id": "material", "title": "1. The material", "fields": [{"id": "how_this_works", "text": "ONE ENTRY IS ONE MATERIAL AS APPROVED: a named product from a named manufacturer. The Entries list is the specification library - material, category, manufacturer and whether it is current - and each entry carries the manufacturer's specification sheet and allergen statement as attachments.\n\nWHAT 2.3.2.2 ASKS FOR. Specifications for all raw materials and packaging that impact finished product safety - ingredients, additives, processing aids, packaging and hazardous chemicals - documented and kept current.\n\nWHY THE BRAND IS PART OF IT. SOP-2.3.4 approves a material bought through a distributor as a named product from a named manufacturer. The approved brand recorded here is what the Brand / Manufacturer column on FRM-301 is checked against at every delivery. A different brand is a new material: record it under Approved alternates only once its allergens have been checked.\n\nA DISCONTINUED MATERIAL STAYS ON THE REGISTER, marked Discontinued. Deleting it would leave no record of what was specified when it was in use.", "type": "info", "label": "How this register works"}, {"id": "material_name", "help": "The site's own name for it. Filled from the pack's product name by the scan in Section 2 - change it if the site calls it something else.", "type": "text", "label": "Material", "width": "half", "required": true, "scanFact": "product_name", "showInList": true}, {"id": "category", "type": "select", "label": "Category", "width": "half", "options": ["Ingredient", "Additive / flavouring", "Processing aid", "Packaging - food contact", "Packaging - not food contact", "Hazardous chemical"], "required": true, "showInList": true}, {"id": "status", "type": "select", "label": "Status", "width": "third", "options": ["Current", "Under review", "Discontinued"], "required": true, "showInList": true}, {"id": "used_in", "help": "The products or process steps that use it.", "type": "textarea", "label": "Where it is used"}]}, {"id": "source", "title": "2. Approved source", "fields": [{"id": "source_info", "text": "Use Scan pack on this section and photograph the label. One photo fills the whole entry where the pack shows it: the manufacturer, product name, item code and net weight here; the storage instruction in Section 3; and in Section 4 the ingredient statement, the Contains statement and any may-contain statement, word for word. The photo is kept on the entry as the evidence for what was transcribed.\n\nIF THE PANEL IS ON ANOTHER SIDE, scan that side too - each scan fills what it can read.\n\nCHECK EVERY VALUE BEFORE SAVING, the allergens above all. The allergen boxes are ticked only from the printed Contains statement, never guessed from the ingredient list; if no Contains statement was readable they are left blank and the scan says so.\n\nBOUGHT FROM is the distributor or supplier, chosen from the approved supplier register - it is not on the pack, so the scan never fills it.", "type": "info", "label": "Photograph the pack to fill this entry"}, {"id": "manufacturer", "type": "text", "label": "Manufacturer / brand", "width": "half", "required": true, "scanFact": "brand", "showInList": true}, {"id": "manufacturer_product", "type": "text", "label": "Manufacturer's product name", "width": "half", "required": true, "scanFact": "product_name"}, {"id": "item_code", "type": "text", "label": "Manufacturer / distributor item code", "width": "third", "scanFact": "item_code"}, {"id": "pack_size", "type": "text", "label": "Net weight / pack size", "width": "third", "scanFact": "net_weight"}, {"id": "bought_from", "help": "Only suppliers with a submitted FRM-202 approval (Approved or Conditionally Approved) can be chosen - the same list as REP-201.", "type": "select", "label": "Bought from", "width": "third", "options": [], "multiple": true, "required": true, "scanFact": "none", "optionsFrom": {"form": "FRM-202", "field": "supplier_name", "filters": [{"op": "in", "field": "supplier_status", "values": ["APPROVED – meets all documentation or recognized-distributor requirements.", "CONDITIONALLY APPROVED – lacks one or more documents but poses low food-safety risk (recognized distributor)."]}], "emptyText": "No supplier has a submitted approval yet. Approve the supplier on FRM-202 and submit it; it then appears here."}}, {"id": "alternates", "help": "Other brands accepted for this material. A brand is added here only after its allergen declaration has been checked against Section 4; if its allergens differ, it needs the SQF Practitioner's review first, because the allergen statement on finished product may have to change.", "rows": {"mode": "dynamic", "addLabel": "Add alternate brand"}, "type": "grid", "label": "Approved alternates", "columns": [{"id": "brand", "type": "text", "label": "Manufacturer / brand", "width": 3}, {"id": "product", "type": "text", "label": "Product name / code", "width": 3}, {"id": "allergens_same", "type": "select", "label": "Allergens vs approved", "width": 2, "options": ["Same", "Different - reviewed"]}, {"id": "approved_on", "type": "date", "label": "Approved on", "width": 2}, {"id": "notes", "type": "text", "label": "Notes", "width": 3}]}], "scanMode": "specification", "scanLabel": true, "scanScope": "form"}, {"id": "specification", "title": "3. Specification (2.3.2.2)", "fields": [{"id": "spec_info", "text": "ATTACH THE MANUFACTURER'S SPECIFICATION SHEET to this entry - the Attachments section is at the bottom. For a branded product bought through a distributor this document takes the place of a certificate of analysis for each lot, which a distributor does not issue.\n\nWhere no specification exists - common for commodity items - record what the site specifies instead in the description below, and say so. A blank is not a specification.", "type": "info", "label": "What the specification is"}, {"id": "spec_on_file", "type": "select", "label": "Manufacturer specification", "width": "half", "options": ["Attached to this entry", "Held elsewhere - named below", "Requested, not yet received", "None issued - site specification below"], "required": true}, {"id": "spec_location", "type": "text", "label": "Where it is held", "width": "half"}, {"id": "spec_issue_date", "help": "The date printed on the manufacturer's sheet, so a newer one can be recognised.", "type": "date", "label": "Specification issue date", "width": "third"}, {"id": "description", "help": "What the material is and what it must be - form, colour, key limits the manufacturer states.", "type": "textarea", "label": "Description and key characteristics", "required": true}, {"id": "storage", "type": "select", "label": "Storage", "width": "third", "options": ["Ambient", "Chilled - at or below 40°F", "Frozen"], "required": true, "scanFact": "storage"}, {"id": "shelf_life", "help": "Unopened, as stated by the manufacturer; and once opened, where it differs.", "type": "text", "label": "Shelf life", "width": "third"}]}, {"id": "allergens", "title": "4. Allergens", "fields": [{"id": "allergen_info", "text": "Record what the manufacturer declares - the ingredient statement and the Contains statement word for word, and any \"may contain\" or \"made in a facility with\" statement. These are what an alternate brand is checked against at receipt, and they feed the allergen statement on finished product.\n\nFROM A SCAN: the Contains boxes are ticked by matching the words of the printed Contains statement shown below them, so each ticked box can be traced to the pack. A scan never ticks \"None of the major allergens\" - only a person can decide there are none.\n\nCHECK THE TRANSCRIPTION. The first scans of a Pillsbury bag each replaced \"NONFAT MILK, XANTHAN GUM, GUAR GUM\" with a different ingredient that is not on the bag. A scan warns when the Contains statement declares an allergen the ingredient statement no longer names, and unticks the confirmation below whenever it fills either statement, so an entry cannot be submitted until a person has compared them with the pack.", "type": "info", "label": "Read the declaration, not the product name"}, {"id": "ingredient_statement", "help": "Word for word from the pack or specification sheet.", "type": "textarea", "label": "Ingredient statement (as printed)", "scanFact": "ingredients"}, {"id": "contains_statement", "help": "e.g. \"CONTAINS WHEAT, MILK, SOY AND EGG INGREDIENTS.\" Blank where the pack carries none.", "type": "text", "label": "Contains statement (as printed)", "scanFact": "contains_statement"}, {"id": "declarations_checked", "type": "checkbox", "required": true, "label": "I have checked the ingredient statement and the Contains statement above word for word against the pack or the specification sheet", "help": "Read them side by side, ingredient by ingredient. A scan transcribes them and can misread or drop part of a dense panel.", "clearOnScanOf": ["ingredient_statement", "contains_statement"]}, {"id": "allergens_contains", "type": "select", "label": "Contains", "options": ["Milk", "Egg", "Wheat", "Soy", "Peanut", "Tree nuts", "Sesame", "Fish", "Crustacean shellfish", "None of the major allergens", "Not applicable - not a food ingredient"], "multiple": true, "required": true, "scanFact": "allergens"}, {"id": "may_contain", "help": "Word for word from the pack or statement. Write \"none\" where there is none.", "type": "textarea", "label": "May contain / precautionary statement", "scanFact": "may_contain"}, {"id": "allergen_statement", "type": "select", "label": "Allergen statement", "width": "half", "options": ["Attached to this entry", "On the specification sheet", "Taken from the pack label - photo attached", "Not applicable - not a food ingredient"], "required": true}]}, {"id": "review", "title": "5. Review and approval", "fields": [{"id": "review_info", "text": "2.3.2.2 requires specifications to be KEPT CURRENT. Review each entry at least annually and whenever the manufacturer issues a new sheet, changes the product, or a different brand is bought. Ask the supplier to tell the site of any change in composition - allergens especially - and record that it was asked.", "type": "info", "label": "Keeping it current"}, {"id": "change_notice", "type": "select", "label": "Supplier asked to notify changes in composition", "width": "half", "options": ["Yes - recorded", "Not yet"]}, {"id": "next_review", "type": "date", "label": "Next review of this entry", "width": "half", "required": true}, {"id": "approved_by", "role": "verifier", "type": "signature", "label": "Reviewed and approved by the SQF Practitioner", "required": true, "statement": "This specification is current, the manufacturer and product named are the ones approved for this material, and the allergens recorded match the manufacturer's declaration."}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{material_name} — {manufacturer}"}, "schemaVersion": 1}$fs$::jsonb),
       revision       = 'v3',
       effective_date = date '2026-09-18',
       approved_by    = 'GJM'
 where sop_number = 'FRM-207';

do $verify$
declare fs jsonb; f jsonb; n int;
begin
  select content->'form_schema' into fs from public.sop_documents where sop_number = 'FRM-207';
  select count(*) into n from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') x;
  if n <> 30 then raise exception 'expected 30 fields, found %.', n; end if;
  select x into f from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') x
   where x->>'id' = 'declarations_checked';
  if f is null or f->>'type' <> 'checkbox' or not (f->>'required')::boolean
     or not (f->'clearOnScanOf' ? 'ingredient_statement') or not (f->'clearOnScanOf' ? 'contains_statement') then
    raise exception 'declarations_checked is missing or mis-configured: %', f;
  end if;
  if (select revision from public.sop_documents where sop_number = 'FRM-207') <> 'v3' then
    raise exception 'FRM-207 not revised to v3.';
  end if;
  raise notice 'FRM-207 v3: declarations must be confirmed against the pack before submit.';
end $verify$;

commit;
